# Verify the filled columns
filled_cols = []
for col in range(29):
    all_ones = all(demo_input[r][col] == 1 for r in range(7))
    if all_ones:
        filled_cols.append(col)

print(f"Filled columns (all 1s in input): {filled_cols}")

# So the rule is: any column that is completely filled with 1s, get changed to 2s
# AND the last row (row 6) which is also all 1s becomes all 2s

# Test: apply this rule to get the output
def apply_rule(grid):
    h, w = len(grid), len(grid[0])

    # Find all filled columns
    filled_cols = set()
    for col in range(w):
        if all(grid[r][col] == 1 for r in range(h)):
            filled_cols.add(col)

    # Check if last row is all 1s
    last_row_filled = all(grid[h-1][c] == 1 for c in range(w))

    new_grid = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 and (c in filled_cols or r == h-1 or last_row_filled):
                new_grid[r][c] = 2

    return new_grid

# Compare with expected output
result = apply_rule(demo_input)
match = result == demo_output
print(f"\nRule matches expected output: {match}")

if not match:
    for r in range(7):
        for c in range(29):
            if result[r][c] != demo_output[r][c]:
                print(f"Mismatch at ({r},{c}): got {result[r][c]}, expected {demo_output[r][c]}")

# Test the simpler rule: any line (row or col) filled with 1s becomes a line of 2s

def apply_line_rule(grid):
    h, w = len(grid), len(grid[0])
    new_grid = [[0]*w for _ in range(h)]

    for r in range(h):
        # Check if row is filled with 1s
        if all(grid[r][c] == 1 for c in range(w)):
            for c in range(w):
                new_grid[r][c] = 2
        else:
            for c in range(w):
                new_grid[r][c] = grid[r][c]

    for c in range(w):
        # Check if column is filled with 1s
        if all(grid[r][c] == 1 for r in range(h)):
            for r in range(h):
                new_grid[r][c] = 2

    return new_grid

result = apply_line_rule(demo_input)
print("Result at mismatch positions we see:")
print(f"Row 6: {result[6]}")
print(f"Col 3 (should be all 2s): {[result[r][3] for r in range(7)]}")
print(f"Col 5 (should stay as is): {[result[r][5] for r in range(7)]}")
print(f"Row 0: {result[0]}")
print(f"Expected row 0: {demo_output[0]}")

# Check if result matches
match = result == demo_output
print(f"\nRule matches: {match}")

